sys_script_include.script:
var LeaveRefQual = Class.create();
LeaveRefQual.prototype = {
    initialize: function() {},


    getEventsForLoggedInStudentCollege: function() {

        // Get logged-in Student
        var student = new GlideRecord(
            'x_1790229_edusph_0_student'
        );

        student.addQuery('user', gs.getUserID());
        student.setLimit(1);
        student.query();

        if (!student.next()) {
            return 'sys_idISEMPTY';
        }

        // Get Student's College
        var collegeId = student.getValue('college');

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        // Filter Events by College
        return 'college=' + collegeId;
    },






    getRegisteredStudentsForEvent: function() {

        // Get selected Event from EventProxyRequest
        var eventId = current.getValue('event');

        if (!eventId) {
            return 'sys_idISEMPTY';
        }

        // Find registrations for the selected Event
        var registration = new GlideRecord(
            'x_1790229_edusph_0_event_registration'
        );

        registration.addQuery('event', eventId);
        registration.addNotNullQuery('student');
        registration.query();

        var studentIds = [];

        // Collect registered Student IDs
        while (registration.next()) {

            var studentId = registration.getValue('student');

            if (studentIds.indexOf(studentId) === -1) {
                studentIds.push(studentId);
            }
        }

        if (studentIds.length === 0) {
            return 'sys_idISEMPTY';
        }

        return 'sys_idIN' + studentIds.join(',');
    },





    getSessionsForStudentCollege: function(requestRecord) {

        // Get selected Student
        var studentId = requestRecord.getValue('student');

        if (!studentId) {
            return 'sys_idISEMPTY';
        }

        // Retrieve Student record
        var student = new GlideRecord(
            'x_1790229_edusph_0_student'
        );

        if (!student.get(studentId)) {
            return 'sys_idISEMPTY';
        }

        // Get Student's College
        var collegeId = student.getValue('college');

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        // Filter Class Sessions by College
        return 'college=' + collegeId;
    },


    type: 'LeaveRefQual'
};
